CREATE TABLE public.tournament_goals(game_id uuid NOT NULL REFERENCES public.tournament_games(id) ON DELETE CASCADE,roster_id uuid NOT NULL REFERENCES public.team_roster(id) ON DELETE CASCADE,goals integer NOT NULL CHECK(goals>0),PRIMARY KEY(game_id,roster_id));GRANT SELECT ON public.tournament_goals TO authenticated;GRANT ALL ON public.tournament_goals TO service_role;ALTER TABLE public.tournament_goals ENABLE ROW LEVEL SECURITY;CREATE POLICY "members view scorers" ON public.tournament_goals FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.save_tournament_result(_game uuid,_home integer,_away integer,_goals jsonb,_winner uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.tournament_games; t public.tournaments; v jsonb; a public.team_roster; home_total integer:=0;away_total integer:=0;BEGIN SELECT tournament_id INTO t.id FROM public.tournament_games WHERE id=_game;SELECT * INTO t FROM public.tournaments WHERE id=t.id FOR UPDATE;IF auth.uid() IS NULL OR t.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Somente o organizador salva';END IF;SELECT * INTO g FROM public.tournament_games WHERE id=_game;IF jsonb_typeof(_goals)<>'array' OR jsonb_array_length(_goals)>200 THEN RAISE EXCEPTION 'Artilharia inválida';END IF;FOR v IN SELECT value FROM jsonb_array_elements(_goals) LOOP SELECT * INTO a FROM public.team_roster WHERE id=(v->>'roster_id')::uuid;IF a.team_id NOT IN (g.home_id,g.away_id) OR a.id IS NULL OR (v->>'goals')::integer<=0 THEN RAISE EXCEPTION 'Atleta ou gols inválidos';END IF;IF a.team_id=g.home_id THEN home_total:=home_total+(v->>'goals')::integer;ELSE away_total:=away_total+(v->>'goals')::integer;END IF;END LOOP;IF home_total>_home OR away_total>_away THEN RAISE EXCEPTION 'Gols individuais excedem o placar';END IF;PERFORM public.save_tournament_score(_game,_home,_away,_winner);DELETE FROM public.tournament_goals WHERE game_id=_game;FOR v IN SELECT value FROM jsonb_array_elements(_goals) LOOP INSERT INTO public.tournament_goals(game_id,roster_id,goals) VALUES(_game,(v->>'roster_id')::uuid,(v->>'goals')::integer);END LOOP;END $$;
REVOKE ALL ON FUNCTION public.save_tournament_result(uuid,integer,integer,jsonb,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_tournament_result(uuid,integer,integer,jsonb,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_team_crest() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.crest_path IS NOT NULL AND split_part(NEW.crest_path,'/',1)<>NEW.owner_id::text THEN RAISE EXCEPTION 'Escudo não pertence ao organizador';END IF;RETURN NEW;END $$;CREATE TRIGGER team_crest_owner BEFORE INSERT OR UPDATE ON public.sports_teams FOR EACH ROW EXECUTE FUNCTION public.guard_team_crest();